import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.DYAmjhAm.js";const h=JSON.parse('{"title":"Interface: DataPropertyConfig","description":"","frontmatter":{},"headers":[],"relativePath":"api/interfaces/DataPropertyConfig.md","filePath":"api/interfaces/DataPropertyConfig.md","lastUpdated":null}'),d={name:"api/interfaces/DataPropertyConfig.md"};function n(s,e,i,c,l,p){return t(),r("div",null,[...e[0]||(e[0]=[o('<p><a href="./../">breeze-client</a> / DataPropertyConfig</p><h1 id="interface-datapropertyconfig" tabindex="-1">Interface: DataPropertyConfig <a class="header-anchor" href="#interface-datapropertyconfig" aria-label="Permalink to &quot;Interface: DataPropertyConfig&quot;">​</a></h1><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/dfead84fa6d4ff83e0d0445305f9e6d5367fb61e/src/metadata/entity-metadata.ts#L2238" target="_blank" rel="noreferrer">src/metadata/entity-metadata.ts:2238</a></p><p>Configuration info to be passed to the <a href="./../classes/DataProperty">DataProperty</a> constructor. Either <code>name</code> or <code>nameOnServer</code> is required.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><h3 id="complextypename" tabindex="-1">complexTypeName? <a class="header-anchor" href="#complextypename" aria-label="Permalink to &quot;complexTypeName?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>complexTypeName?</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/dfead84fa6d4ff83e0d0445305f9e6d5367fb61e/src/metadata/entity-metadata.ts#L2250" target="_blank" rel="noreferrer">src/metadata/entity-metadata.ts:2250</a></p><p>The name, short or qualified, of the <a href="./../classes/ComplexType">ComplexType</a> this property holds. Setting it makes the property a complex property; it is linked to the ComplexType once both are in the same MetadataStore.</p><hr><h3 id="concurrencymode" tabindex="-1">concurrencyMode? <a class="header-anchor" href="#concurrencymode" aria-label="Permalink to &quot;concurrencyMode?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>concurrencyMode?</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/dfead84fa6d4ff83e0d0445305f9e6d5367fb61e/src/metadata/entity-metadata.ts#L2270" target="_blank" rel="noreferrer">src/metadata/entity-metadata.ts:2270</a></p><p>How the property takes part in optimistic concurrency checking; see <a href="./../classes/DataProperty#concurrencymode">DataProperty.concurrencyMode</a>. Any value other than <code>&quot;None&quot;</code> makes it a concurrency property.</p><hr><h3 id="custom" tabindex="-1">custom? <a class="header-anchor" href="#custom" aria-label="Permalink to &quot;custom?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>custom?</strong>: <code>any</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/dfead84fa6d4ff83e0d0445305f9e6d5367fb61e/src/metadata/entity-metadata.ts#L2284" target="_blank" rel="noreferrer">src/metadata/entity-metadata.ts:2284</a></p><p>Sets <a href="./../classes/DataProperty#custom">DataProperty.custom</a>.</p><hr><h3 id="datatype" tabindex="-1">dataType? <a class="header-anchor" href="#datatype" aria-label="Permalink to &quot;dataType?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>dataType?</strong>: <code>string</code> | <a href="./../classes/ComplexType"><code>ComplexType</code></a> | <a href="./../classes/DataType"><code>DataType</code></a></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/dfead84fa6d4ff83e0d0445305f9e6d5367fb61e/src/metadata/entity-metadata.ts#L2247" target="_blank" rel="noreferrer">src/metadata/entity-metadata.ts:2247</a></p><p>The <a href="./../classes/DataType">DataType</a> of the property, or its name. Defaults to <a href="./../classes/DataType#string">DataType.String</a>. For a property that holds a complex object, set <code>complexTypeName</code> instead.</p><hr><h3 id="defaultvalue" tabindex="-1">defaultValue? <a class="header-anchor" href="#defaultvalue" aria-label="Permalink to &quot;defaultValue?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>defaultValue?</strong>: <code>any</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/dfead84fa6d4ff83e0d0445305f9e6d5367fb61e/src/metadata/entity-metadata.ts#L2259" target="_blank" rel="noreferrer">src/metadata/entity-metadata.ts:2259</a></p><p>The value a new entity gets for this property. Defaults to <code>null</code> for a nullable property and to the <a href="./../classes/DataType">DataType</a>&#39;s default value otherwise. A numeric default given as a string is parsed.</p><hr><h3 id="displayname" tabindex="-1">displayName? <a class="header-anchor" href="#displayname" aria-label="Permalink to &quot;displayName?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>displayName?</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/dfead84fa6d4ff83e0d0445305f9e6d5367fb61e/src/metadata/entity-metadata.ts#L2277" target="_blank" rel="noreferrer">src/metadata/entity-metadata.ts:2277</a></p><p>The name used for this property in validation messages. Defaults to the property name.</p><hr><h3 id="enumtype" tabindex="-1">enumType? <a class="header-anchor" href="#enumtype" aria-label="Permalink to &quot;enumType?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>enumType?</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/dfead84fa6d4ff83e0d0445305f9e6d5367fb61e/src/metadata/entity-metadata.ts#L2279" target="_blank" rel="noreferrer">src/metadata/entity-metadata.ts:2279</a></p><p>The full name of the server-side enum type, for a property whose values are enum members.</p><hr><h3 id="isnullable" tabindex="-1">isNullable? <a class="header-anchor" href="#isnullable" aria-label="Permalink to &quot;isNullable?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>isNullable?</strong>: <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/dfead84fa6d4ff83e0d0445305f9e6d5367fb61e/src/metadata/entity-metadata.ts#L2253" target="_blank" rel="noreferrer">src/metadata/entity-metadata.ts:2253</a></p><p>Whether the property may be null. Defaults to <code>true</code>. Breeze does not create a <code>required</code> validator from it; that comes with the server&#39;s metadata.</p><hr><h3 id="ispartofkey" tabindex="-1">isPartOfKey? <a class="header-anchor" href="#ispartofkey" aria-label="Permalink to &quot;isPartOfKey?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>isPartOfKey?</strong>: <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/dfead84fa6d4ff83e0d0445305f9e6d5367fb61e/src/metadata/entity-metadata.ts#L2261" target="_blank" rel="noreferrer">src/metadata/entity-metadata.ts:2261</a></p><p>Whether the property is part of its EntityType&#39;s key. Defaults to <code>false</code>.</p><hr><h3 id="isscalar" tabindex="-1">isScalar? <a class="header-anchor" href="#isscalar" aria-label="Permalink to &quot;isScalar?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>isScalar?</strong>: <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/dfead84fa6d4ff83e0d0445305f9e6d5367fb61e/src/metadata/entity-metadata.ts#L2256" target="_blank" rel="noreferrer">src/metadata/entity-metadata.ts:2256</a></p><p>Whether the property holds a single value. Defaults to <code>true</code>; set it to <code>false</code> for a property that holds an array of values or complex objects.</p><hr><h3 id="issettable" tabindex="-1">isSettable? <a class="header-anchor" href="#issettable" aria-label="Permalink to &quot;isSettable?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>isSettable?</strong>: <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/dfead84fa6d4ff83e0d0445305f9e6d5367fb61e/src/metadata/entity-metadata.ts#L2267" target="_blank" rel="noreferrer">src/metadata/entity-metadata.ts:2267</a></p><p>Whether the property can be written. Defaults to <code>true</code>. Breeze does not set a property that is not settable when it populates an entity from query results.</p><hr><h3 id="isunmapped" tabindex="-1">isUnmapped? <a class="header-anchor" href="#isunmapped" aria-label="Permalink to &quot;isUnmapped?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>isUnmapped?</strong>: <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/dfead84fa6d4ff83e0d0445305f9e6d5367fb61e/src/metadata/entity-metadata.ts#L2264" target="_blank" rel="noreferrer">src/metadata/entity-metadata.ts:2264</a></p><p>Whether the property exists only on the client, with no counterpart on the server. Defaults to <code>false</code>. Breeze marks the properties it discovers on a registered constructor as unmapped itself.</p><hr><h3 id="maxlength" tabindex="-1">maxLength? <a class="header-anchor" href="#maxlength" aria-label="Permalink to &quot;maxLength?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>maxLength?</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/dfead84fa6d4ff83e0d0445305f9e6d5367fb61e/src/metadata/entity-metadata.ts#L2273" target="_blank" rel="noreferrer">src/metadata/entity-metadata.ts:2273</a></p><p>The maximum length of a string value. Breeze does not create a <code>maxLength</code> validator from it; that comes with the server&#39;s metadata.</p><hr><h3 id="name" tabindex="-1">name? <a class="header-anchor" href="#name" aria-label="Permalink to &quot;name?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>name?</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/dfead84fa6d4ff83e0d0445305f9e6d5367fb61e/src/metadata/entity-metadata.ts#L2241" target="_blank" rel="noreferrer">src/metadata/entity-metadata.ts:2241</a></p><p>The client-side name of the property. If omitted, it is derived from <code>nameOnServer</code> by the store&#39;s <a href="./../classes/NamingConvention">NamingConvention</a> when the property&#39;s type is added to a <a href="./../classes/MetadataStore">MetadataStore</a>.</p><hr><h3 id="nameonserver" tabindex="-1">nameOnServer? <a class="header-anchor" href="#nameonserver" aria-label="Permalink to &quot;nameOnServer?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>nameOnServer?</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/dfead84fa6d4ff83e0d0445305f9e6d5367fb61e/src/metadata/entity-metadata.ts#L2244" target="_blank" rel="noreferrer">src/metadata/entity-metadata.ts:2244</a></p><p>The name of the property on the server. If omitted, it is derived from <code>name</code> by the store&#39;s <a href="./../classes/NamingConvention">NamingConvention</a>.</p><hr><h3 id="rawtypename" tabindex="-1">rawTypeName? <a class="header-anchor" href="#rawtypename" aria-label="Permalink to &quot;rawTypeName?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>rawTypeName?</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/dfead84fa6d4ff83e0d0445305f9e6d5367fb61e/src/metadata/entity-metadata.ts#L2282" target="_blank" rel="noreferrer">src/metadata/entity-metadata.ts:2282</a></p><p>The server&#39;s name for the property&#39;s type, when the client has no matching <a href="./../classes/DataType">DataType</a> and <code>dataType</code> is <a href="./../classes/DataType#undefined">DataType.Undefined</a>.</p><hr><h3 id="validators" tabindex="-1">validators? <a class="header-anchor" href="#validators" aria-label="Permalink to &quot;validators?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>validators?</strong>: <a href="./../classes/Validator"><code>Validator</code></a>[]</p></blockquote><p>Defined in: <a href="https://github.com/Breeze/breeze-client-v3/blob/dfead84fa6d4ff83e0d0445305f9e6d5367fb61e/src/metadata/entity-metadata.ts#L2275" target="_blank" rel="noreferrer">src/metadata/entity-metadata.ts:2275</a></p><p>The <a href="./../classes/Validator">Validator</a>s for this property. Defaults to an empty array.</p>',89)])])}const m=a(d,[["render",n]]);export{h as __pageData,m as default};
